00117     public function createWindow($parent, $wclass, $caption, $xPos, $yPos, $width, $height, $style = null, $params = null): mixed
00118     {
00119         global $bearsamppCore;
00120 
00121         // Fix for PHP 8.4: Convert null to 0 for parent parameter
00122         $parent = $parent === null ? 0 : $parent;
00123 
00124         // Fix for PHP 8.4: Ensure style and params are proper types
00125         $style = $style === null ? 0 : $style;
00126         $params = $params === null ? 0 : $params;
00127 
00128         // Log window creation attempt for debugging
00129         $this->writeLog('Creating window: class=' . $wclass . ', caption=' . $caption . ', pos=(' . $xPos . ',' . $yPos . '), size=(' . $width . 'x' . $height . '), style=' . $style . ', params=' . $params);
00130 
00131         $caption = empty($caption) ? $this->defaultTitle : $this->defaultTitle . ' - ' . $caption;
00132         $window  = $this->callWinBinder('wb_create_window', array($parent, $wclass, $caption, $xPos, $yPos, $width, $height, $style, $params));
00133 
00134         if ($window === false || $window === null) {
00135             $this->writeLog('ERROR: Failed to create window - wb_create_window returned: ' . var_export($window, true));
00136             // Check if WinBinder extension is loaded
00137             if (!extension_loaded('winbinder')) {
00138                 $this->writeLog('ERROR: WinBinder extension is not loaded!');
00139             }
00140             // Check if the function exists
00141             if (!function_exists('wb_create_window')) {
00142                 $this->writeLog('ERROR: wb_create_window function does not exist!');
00143             }
00144         } else {
00145             $this->writeLog('Window created successfully: handle=' . $window);
00146             // Set tiny window icon
00147             // Use bmp for window icon to ensure orange icon is used everywhere as requested
00148             $this->setImage($window, Path::getImagesPath() . '/bearsampp.bmp');
00149         }
00150 
00151         return $window;
00152     }
