00163     private function callWinBinder($function, $params = array(), $removeErrorHandler = false): mixed
00164     {
00165         $result = false;
00166         if (function_exists($function)) {
00167             if ($removeErrorHandler) {
00168                 // Suppress all errors for this call
00169                 $oldErrorLevel = error_reporting(0);
00170                 $result = @call_user_func_array($function, $params);
00171                 error_reporting($oldErrorLevel);
00172             } else {
00173                 $result = call_user_func_array($function, $params);
00174             }
00175         }
00176 
00177         return $result;
00178     }
