00244     public function destroyWindow($window): bool
00245     {
00246         // Check if window exists and is valid
00247         if (!$window || !$this->windowIsValid($window)) {
00248             return true; // Already closed or invalid window
00249         }
00250 
00251         // Get window title before destruction for fallback
00252         $windowTitle = $this->getText($window);
00253         $currentPid = Win32Ps::getCurrentPid();
00254 
00255         // Attempt standard destruction
00256         $this->callWinBinder('wb_destroy_window', array($window));
00257 
00258         // Verify closure with retries
00259         $maxAttempts = 3;
00260         $attempt     = 0;
00261         $destroyed   = false;
00262 
00263         while ($attempt < $maxAttempts && !$destroyed) {
00264             $this->processMessages();
00265             usleep(100000); // 100ms delay
00266             $destroyed = !$this->windowIsValid($window);
00267             $attempt++;
00268         }
00269 
00270         // Fallback to process termination if window still exists
00271         if (!$destroyed) {
00272             // 1. Try to close using window title
00273             $this->exec('taskkill', '/FI "WINDOWTITLE eq ' . $windowTitle . '" /F', true);
00274 
00275             // 2. Try to kill process directly using Winbinder's PID method
00276             $currentPid = Win32Ps::getCurrentPid();
00277             if (!empty($currentPid)) {
00278                 $this->exec('taskkill', '/PID ' . $currentPid . ' /T /F', true);
00279                 $this->writeLog('Force-killed PID: ' . $currentPid . ' for window: ' . $window);
00280             }
00281 
00282             // 3. Final sanity check
00283             if ($this->windowIsValid($window)) {
00284                 $this->callWinBinder('wb_destroy_window', array($window), true); // Force native call
00285             }
00286 
00287             // 4. Reset internal state to prevent memory leaks
00288             $this->reset();
00289         }
00290 
00291         // Final verification
00292         return !$this->windowIsValid($window);
00293     }
