00346     public function exec($cmd, $params = null, $silent = false, $wait = true): mixed
00347     {
00348         // Handle array of arguments by quoting each one individually
00349         if (is_array($params)) {
00350             $quotedParams = [];
00351             foreach ($params as $arg) {
00352                 $quotedParams[] = $this->quoteWindowsArg((string)$arg);
00353             }
00354             $params = implode(' ', $quotedParams);
00355         }
00356 
00357         if ($silent) {
00358             // Use WScript.Shell via COM for true silent execution (zero window flashing)
00359             // This is more reliable than powershell.exe -WindowStyle Hidden which can still flash
00360             try {
00361                 $wsh = new COM('WScript.Shell');
00362                 $fullCmd = '"' . $cmd . '"' . (empty($params) ? '' : ' ' . $params);
00363                 // 0 = Hidden, $wait = wait for process to exit
00364                 $exitCode = $wsh->Run($fullCmd, 0, $wait);
00365                 $this->writeLog('exec (silent via COM): ' . $fullCmd . ' [ExitCode: ' . $exitCode . ']');
00366                 return $exitCode === 0;
00367             } catch (Throwable $e) {
00368                 $this->writeLog('exec (silent via COM) failed: ' . $e->getMessage() . '. Falling back to PowerShell.');
00369                 // Fall back to PowerShell method if COM fails
00370                 $psCmd = 'Start-Process -FilePath \'' . str_replace("'", "''", $cmd) . '\'';
00371                 if (!empty($params)) {
00372                     $psCmd .= ' -ArgumentList \'' . str_replace("'", "''", $params) . '\'';
00373                 }
00374                 $psCmd .= ' -WindowStyle Hidden';
00375                 if ($wait) {
00376                     $psCmd .= ' -Wait';
00377                 }
00378                 $encodedCmd = base64_encode(mb_convert_encoding($psCmd, 'UTF-16LE', 'UTF-8'));
00379                 $cmd = 'powershell.exe';
00380                 $params = '-WindowStyle Hidden -ExecutionPolicy Bypass -EncodedCommand ' . $encodedCmd;
00381             }
00382         }
00383 
00384         $this->writeLog('exec: ' . $cmd . ' ' . $params);
00385 
00386         return $this->callWinBinder('wb_exec', array($cmd, $params));
00387     }
00388 
00401     private function quoteWindowsArg(string $arg): string
00402     {
00403         // If argument is empty, return empty quotes
00404         if ($arg === '') {
00405             return '""';
00406         }
00407 
00408         // If argument contains spaces, quotes, or special shell characters, it needs quoting
00409         if (preg_match('/[\s"&|<>^()]/', $arg)) {
00410             // Escape any internal quotes by doubling them (Windows convention for cmd.exe/WScript.Shell)
00411             $escaped = str_replace('"', '""', $arg);
00412             return '"' . $escaped . '"';
00413         }
00414 
00415         return $arg;
00416     }
