01042     public function setProgressBarValue($progressBar, $value)
01043     {
01044         if ($progressBar != null && isset($progressBar[self::CTRL_OBJ]) && isset($this->gauge[$progressBar[self::CTRL_OBJ]])) {
01045             if (strval($value) == self::INCR_PROGRESS_BAR) {
01046                 $value = $this->gauge[$progressBar[self::CTRL_OBJ]] + 1;
01047             }
01048             if (is_numeric($value)) {
01049                 $this->gauge[$progressBar[self::CTRL_OBJ]] = $value;
01050 
01051                 // Check if the control is still valid before setting the value
01052                 // This prevents errors when the parent window has been destroyed
01053                 $this->callWinBinder('wb_set_value', array($progressBar[self::CTRL_OBJ], $value), true);
01054             }
01055         }
01056     }
