01114     public function messageBox($message, $type, $title = null)
01115     {
01116         global $bearsamppCore;
01117 
01118         $message    = str_replace(self::NEW_LINE, PHP_EOL, $message);
01119         $messageBox = $this->callWinBinder('wb_message_box', array(
01120             0, // Use 0 instead of null for the window handle parameter
01121             strlen($message) < 64 ? str_pad($message, 64) : $message, // Pad message to display entire title
01122             $title == null ? $this->defaultTitle : $this->defaultTitle . ' - ' . $title,
01123             $type
01124         ));
01125 
01126         return $messageBox;
01127     }
