01235 function __winbinderEventHandler($window, $id, $ctrl, $param1, $param2)
01236 {
01237     global $bearsamppWinbinder;
01238 
01239     if ($bearsamppWinbinder->callback[$window][2] != null) {
01240         $bearsamppWinbinder->destroyTimer($window, $bearsamppWinbinder->callback[$window][2][0]);
01241     }
01242 
01243     call_user_func_array(
01244         array($bearsamppWinbinder->callback[$window][0], $bearsamppWinbinder->callback[$window][1]),
01245         array($window, $id, $ctrl, $param1, $param2)
01246     );
01247 }
